  "README.md": "# Expojet Expo app\n\nThis project was generated from the checksum-verified Expo SDK 58 base pack.\n\n## Run\n\n```powershell\npnpm install\nCopy-Item .env.example .env\npnpm start -- --clear\n```\n\nOpen Expo Go and scan the QR code. Configure only public mobile variables in `.env`: values prefixed with `EXPO_PUBLIC_` are embedded in the bundle. Never put database URLs, server secrets, Clerk secret keys, or Convex admin keys in this file. Provider adapters add their required variables to `.env.example`; follow the generated README for provider-specific setup.\n",
  "src/onboarding/provider.tsx": "import * as SecureStore from \"expo-secure-store\";\nimport {\n  createContext,\n  type PropsWithChildren,\n  useContext,\n  useEffect,\n  useMemo,\n  useState,\n} from \"react\";\n\nconst STORAGE_KEY = \"expojet.onboarding.v1\";\ntype OnboardingState = {\n  status: \"loading\" | \"ready\";\n  complete: boolean;\n  finish(): Promise<void>;\n  reset(): Promise<void>;\n};\nconst OnboardingContext = createContext<OnboardingState | null>(null);\n\nexport function OnboardingProvider({ children }: PropsWithChildren) {\n  const [status, setStatus] = useState<OnboardingState[\"status\"]>(\"loading\");\n  const [complete, setComplete] = useState(false);\n  useEffect(() => {\n    SecureStore.getItemAsync(STORAGE_KEY)\n      .then((value) => setComplete(value === \"complete\"))\n      .catch(() => setComplete(false))\n      .finally(() => setStatus(\"ready\"));\n  }, []);\n  const value = useMemo<OnboardingState>(\n    () => ({\n      status,\n      complete,\n      finish: async () => {\n        await SecureStore.setItemAsync(STORAGE_KEY, \"complete\");\n        setComplete(true);\n      },\n      reset: async () => {\n        await SecureStore.deleteItemAsync(STORAGE_KEY);\n        setComplete(false);\n      },\n    }),\n    [status, complete],\n  );\n  return <OnboardingContext.Provider value={value}>{children}</OnboardingContext.Provider>;\n}\n\nexport function useOnboarding() {\n  const value = useContext(OnboardingContext);\n  if (!value) throw new Error(\"useOnboarding must be used inside OnboardingProvider\");\n  return value;\n}\n",
  "src/session/types.ts": "export type SessionStatus = \"loading\" | \"authenticated\" | \"unauthenticated\";\n\nexport interface SessionState {\n  status: SessionStatus;\n  user: { id: string; displayName?: string } | null;\n  signIn(): void;\n  signOut(): void;\n}\n",
